#include <stdio.h>

int main(void)
{
    FILE *f = tmpfile();
    if (f == NULL) {
        return 1;
    }
    fputs("AB", f);
    rewind(f);
    FILE *alias = f;
    int first = fgetc(alias);
    int second = fgetc(f);
    printf("%c%c\n", first, second);
    fclose(f);
    return 0;
}

#include <stdio.h>

int main(void)
{
    FILE *f = tmpfile();
    if (f == NULL) {
        return 1;
    }
    fputs("fee", f);
    rewind(f);
    int n = 0;
    while (fgetc(f) != EOF) {
        n++;
    }
    printf("%d\n", n);
    fclose(f);
    return 0;
}
